def keyids_from_pubring(gpgdir):
    if not os.path.exists(gpgdir):
        return []

    with pubring_dir(gpgdir):
        ctx = gpgme.Context()
        keyids = []
        for k in ctx.keylist():
            for subkey in k.subkeys:
                if subkey.can_sign:
                    keyids.append(subkey.keyid)
        return keyids


